import React from 'react';
import ImageWithFallback from './ImageWithFallback';

const CaseCard = ({ case: caseData, onOpen, balance = Infinity }) => {
  const affordable = Number(balance) >= Number(caseData.price);
  const accent = caseData.color || '#3b82f6';
  const itemCount = Array.isArray(caseData.items) ? caseData.items.length : null;

  return (
    <article className="case-card-premium" style={{ '--case-accent': accent }}>
      <div className="case-card-glow" />
      <div className="case-image-container">
        <div className="case-card-badge">WELLCASE</div>
        <ImageWithFallback
          src={caseData.image_url}
          alt={caseData.name}
          className="case-image img-fluid"
        />
      </div>

      <div className="case-card-content">
        <div className="case-card-meta">
          <span>CASE DROP</span>
          {itemCount !== null && <span>{itemCount} DROPS</span>}
        </div>
        <h3>{caseData.name}</h3>
        <p>{caseData.description || 'Des skins rares, des surprises et une chance de faire exploser ton inventaire.'}</p>

        <div className="case-card-footer">
          <div className="case-price">
            <span>PRIX</span>
            <strong>{Number(caseData.price).toLocaleString('fr-FR')} €</strong>
          </div>
          <button
            className="case-open-btn"
            disabled={!affordable}
            onClick={() => onOpen(caseData.id)}
          >
            <span>{affordable ? 'OUVRIR' : 'SOLDE INSUFFISANT'}</span>
            {affordable && <b>↗</b>}
          </button>
        </div>
      </div>
    </article>
  );
};

export default CaseCard;
